function UIActionCityStoreDialog:OnFocus(focus)
    if focus then
        local vo = ActionUtils.GetRegionStoresVo(self._storeId)
        if vo then
            local t = CfUtils.Split(vo.goodId)
            CfUtils.RefreshTopGoods(t)
        end
    end
end

function UIActionCityStoreDialog:OnBtnLevelGroup()    
    self._idleTime = 0
    UIModule.OpenDialog({ id = Constants.UITypeIds.ActionImpressionFavorabilityDialog, parameters = {mapId = self._mapId} }, {
        --{ id = Constants.UITypeIds.UIActionSecondMapDialog }
    })
end

function UIActionCityStoreDialog:InitData()    
    self.toggleData = {}
    for k, v in pairs(self._itemMap) do
        local t = {}
        for i, item in pairs(v) do
            ---@type StoreGoodsDojo
            local dojo = StoreGoodsDojo.New()
            dojo:Fill(item)
            table.insert(t, dojo)
        end
        table.insert(self.toggleData, {
            areaId = checkNumber(k),
            data = t
        })
    end

    table.sort(self.toggleData, function(a, b)
        return checkNumber(a.areaId) < checkNumber(b.areaId)
    end)

    if self._curSelecltInd == 0 then
        self._curSelecltInd = checkNumber(self._storeId)
    end
end

function UIActionCityStoreDialog:FillSelf()
    self:FillLabelInfo()
    self:RefreshItemData()

    CfUtils.FillText(self.TextNumber, CfUtils.GetTimeHMS(self._leftTime))
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self._leftTime = self._leftTime - 1
        --推迟一秒刷新
        if self._leftTime == -1 then
            --刷新
            GameUtils.Request(Interfaces.RegionalMerchantGetProducts, {}, function(request, response)
                if checkNumber(response.errCode) ~= 0 then
                    return
                end
                local jsonData = response.data
                
                self._itemMap = checkTable(jsonData.products)
                self._leftTime = checkNumber(jsonData.leftTime)
    
                self:InitData()
                self:FillSelf()
            end)
        end

        ActionComponent:SetStoreRemainTime(self._leftTime)
        CfUtils.FillText(self.TextNumber, CfUtils.GetTimeHMS(self._leftTime))
    end, CountDownTime, false, true)
end

function UIActionCityStoreDialog:FillRoleInfo()
    local vo = ActionUtils.GetRegionPrimaryMapVo(self._mapId)
    if vo then
        CfUtils.FillImage(self.controller.gameObject.transform:Find("BackGround"), vo.taskImage)
    end
    CfUtils.SafeDelete(self._spineGo, true)
    self._spineGo = nil
    vo = ActionUtils.GetRegionStoresVo(self._mapId)
    local loader = ResourceModule.LoadBundleSync(vo.resource, nil, true)
    if loader.IsSuccess then
        local go = loader:Instantiate(self.Spine.transform)
        go.transform.localPosition = Vector3(0, 0, 0)
        go.transform.localScale = Vector3(1, 1, 1)
        self._spineGo = go.gameObject:GetComponent(typeof(SkeletonGraphic))
    end

    loader:Release()
    self:FillLikabilityInfo()
end

function UIActionCityStoreDialog:OnFixUpdate()
    self._idleTime = self._idleTime + CS.UnityEngine.Time.deltaTime
    if self._idleTime > 7 then
        self._idleTime = 0
        self:PlayStoreAni(StoreStatus.Type5)
    end
    self._time1 = self._time1 + CS.UnityEngine.Time.deltaTime
    self._time2 = self._time2 + CS.UnityEngine.Time.deltaTime
end

function UIActionCityStoreDialog:PlayStoreAni(aniType)
    if aniType == StoreStatus.Type6 then
        -->7才播放
        if self._time1 < 7 then
            return
        else
            self._time1 = 0
        end
    elseif aniType == StoreStatus.Type8 then
        -->7才播放
        if self._time2 < 7 then
            return
        else
            self._time2 = 0
        end
    end
    aniType = StoreStatus.Type1
    self._curType = aniType

    if self._storeCo ~= nil then
        cs_coroutine.stop(self._storeCo)
        self._storeCo = nil
    end
    print(aniType)
    self._storeCo = cs_coroutine.start(function()
        local t = ActionUtils.GetAllAnimaorIdByActionId(self._mapId, 2, aniType)
        if table.count(t) <= 0 then
            return
        end
        local num = math.random(table.count(t))
        local id = t[num]
    
        local vo = ActionUtils.GetRegionStoreAnimatorVo(id)
        if not vo then
            return
        end
    
        CfUtils.FillText(self.TxtState, vo.line)
        CfUtils.SetActive(self.DialogGroup, not string.isEmpty(checkString(vo.line)))

        GameUtils.GetCriWareUtils().PlayVoiceById(vo.soundEffects)

        local isLoop = (aniType == StoreStatus.Type1)
        CfUtils.PlaySpine(self._spineGo, vo.animation, isLoop)
        print(vo.animation)

        --if aniType ~= StoreStatus.Type1 then
        --    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(CfUtils.GetSpineTime(self._spineGo, vo.animation)))
        --    if checkNumber(self._nextType) > 0 then
        --        self:PlayStoreAni(self._nextType)
        --        self._nextType = 0
        --    else
        --        self:PlayStoreAni(StoreStatus.Type1)
        --    end
        --end
    end)
end

