--标签
function UIActionCityStoreDialog:FillLabelInfo()
    if self._isInitLoopList then
        GameUtils.ReloadData(self.ScrollView, table.count(self.toggleData))
    else
        self.ScrollView:InitListView(table.count(self.toggleData), Bind(self, self.OnRefreshIndex))
        self._isInitLoopList = true
    end
end

function UIActionCityStoreDialog:OnRefreshIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local data = self.toggleData[index + 1]
    local isUnlock, err = ActionUtils.IsUnlockRegionalPoint(data.areaId)
    ---@type RegionPrimaryMapVo
    local vo = ActionUtils.GetRegionPrimaryMapVo(data.areaId)
    local go = cell.gameObject
    CfUtils.FillText(go.transform:Find("BtnNode/StateGroup/TxtTabName"), vo.name)
    CfUtils.SetActive(go.transform:Find("BtnNode/ImgSelect"), (index + 1) == self._curSelecltInd)
    CfUtils.SetActive(go.transform:Find("BtnNode/StateGroup/ImgLock"), not isUnlock)

    local shadowComp = go.transform:Find("BtnNode/StateGroup/TxtTabName"):GetComponent(typeof(Shadow))
    if not isUnlock then
        shadowComp.enabled = false
    else
        shadowComp.enabled = true  
    end
    CfUtils.SetActive(go.transform:Find("BtnNode/StateGroup/ImgLock/ImgIcon"), (index + 1) == self._curSelecltInd and 2 or 1)


    SetButtonAction(go.transform:Find("BtnNode"), function()
        self._idleTime = 0
        local ind = checkNumber(self._curSelecltInd)
        if ind > 0 then
            local lastGo = self.ScrollView:GetShownItemByItemIndex(checkNumber(self._curSelecltInd) - 1)
            if lastGo then
                CfUtils.SetActive(lastGo.transform:Find("BtnNode/ImgSelect"), false)
                CfUtils.SetUISwitchImage(lastGo.transform:Find("BtnNode/StateGroup/ImgLock/ImgIcon"), 1)
            end
        end 

        self._curSelecltInd = index + 1
        CfUtils.SetActive(go.transform:Find("BtnNode/ImgSelect"), true)
        CfUtils.SetUISwitchImage(go.transform:Find("BtnNode/StateGroup/ImgLock/ImgIcon"), 2)
        self._mapId = vo.id
        self:FillRoleInfo()
        self:RefreshItemData()

        self:PlayStoreAni(StoreStatus.Type6)
    end)
    return cell
end

function UIActionCityStoreDialog:RefreshItemData()
    if not self._itemMap then
        return {}
    end

    local data = self.toggleData[self._curSelecltInd]
    self._allItems = data.data
    self:FillItems()
end


function UIActionCityStoreDialog:SortItems()
    local t = checkTable(self._allItems)
    table.sort(t, function(a, b)
        local aKey = checkNumber(a.productId)
        local bKey = checkNumber(b.productId)
        if aKey == bKey then
            local vo1 = ActionUtils.GetRegionStoreGoodsVo(a.productId)
            local vo2 = ActionUtils.GetRegionStoreGoodsVo(b.productId)
            if checkNumber(vo2.unlockNum) == checkNumber(vo1.unlockNum) then
                aKey = checkNumber(a.productId)
                bKey = checkNumber(b.productId)
                return aKey > bKey
            end
            return checkNumber(vo2.unlockNum) > checkNumber(vo1.unlockNum)
        else
            return aKey > bKey
        end
    end)
end

function UIActionCityStoreDialog:FillItems()
    self:SortItems()

    if not self.GoodsList.IsListViewInit then
        self.GoodsList:InitGridView(table.count(self._allItems), Bind(self, self.OnGetItemByIndex))
    else
        self.GoodsList:SetListItemCount(0)
        self.GoodsList:SetListItemCount(table.count(self._allItems))
        --GameUtils.ReloadData(self.GoodsList, 0)
        --GameUtils.ReloadData(self.GoodsList, table.count(self._allItems))
    end
end

function UIActionCityStoreDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local ind = index + 1
    local cell = listView:NewListViewItem("OverseaStoreItemCell")
    local data = self._allItems[ind]
    ---@type GroceryBaseNodeListCell
    local nodeScr = CfUtils.GetLuaScr(cell, CellPath)
    if isNull(nodeScr) then return nil end
    nodeScr:SetIndex(ind)
    nodeScr:SetClickCallback(function(position)
        local itemData = self._allItems[position]
        self:PlayStoreAni(StoreStatus.Type8)
        local isLocked = GroceryUtils.ProductIsLocked(itemData)
        if isLocked then
            GameUtils.Toast(localize("商品未解锁"))
            return
        end
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = {
            goodsId        = itemData.icon,
            goodsNum       = itemData.num,
            prices         = itemData.prices,
            coinPrices     = itemData.coinPrices,
            maxBuyNum      = itemData.currentStock,
            rewards        = itemData.rewards,
            remainTime     = itemData.refreshTime,
            endTime        = itemData.nextRefreshLeftSeconds,
            refreshType    = itemData.refreshType,
            buyCb          = function (price, buyNum)
                local currency =  itemData.prices[1].currency
                local productId = itemData.productId
                print(productId)
                GameUtils.Request(Interfaces.RegionalMerchantGetBuy, {shopId = productId, num = buyNum, currency = currency}, function(request, response)
                    if checkNumber(response.errCode) ~= 0 then
                        return
                    end
                    local jsonData = response.data

                    if itemData.currentStock ~= -1 then
                        itemData.currentStock = checkNumber(itemData.currentStock) - buyNum
                    end
                    GoodsUtils.DrawRewards(jsonData.rewards)
                    GoodsUtils.DrawRewards({{
                                                goodsId = currency,
                                                num = -(buyNum * checkNumber(price.current))
                                            }}, true)

                    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = {rewards = jsonData.rewards}})
                    --刷新列表
                    self:FillLabelInfo()
                    self:FillItems()
                end)
            end
        }})
    end)
    nodeScr:RefreshCell(data, ind)
    --if scr then
    --    scr:Refresh(data, function(buyNum)
    --        ---先加个判定  过滤掉报错  这里不影响商店刷新
    --        --if t then
    --            self._allItems[index + 1].num = self._allItems[index + 1].stock - buyNum
    --        --end
    --
    --        self:PlayStoreAni(StoreStatus.Type8)
    --    end)
    --end
    return cell
end

function UIActionCityStoreDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
        self._isInSecondMap = false
        local dialogs = UIModule.CurrentScreen.dialogs
        for _, dialog in pairs(dialogs) do
            if checkNumber(dialog.Argument.id) == Constants.UITypeIds.UIActionSecondMapDialog then
                self._isInSecondMap = true
            end
        end

        self._storeId = checkNumber(argument.storeId)
        self._curSelecltInd = checkNumber(argument.labInd)
        if self._storeId <= 0 then
            return
        end
        local vo = ActionUtils.GetRegionStoresVo(self._storeId)
        self._mapId = checkNumber(vo.region)
        self._mapGo = RegionQuestMgr:GetInstance():GetCurMapGo(self._mapId)
        self._mapCam = self._mapGo.transform:Find("AreaMap_01_01_Camera").gameObject:GetComponent(typeof(Camera))

        self:FillRoleInfo()
        GameUtils.Request(Interfaces.RegionalMerchantGetProducts, {sellerId = self._storeId}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
                return
            end
            local jsonData = response.data
            
            self._itemMap = checkTable(jsonData.products)
            self._leftTime = checkNumber(jsonData.leftTime)

            self:InitData()
            self:FillSelf()
        end)
    end))
    return coWait
end

function UIActionCityStoreDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not self._isInSecondMap then
            RegionQuestMgr:GetInstance():ClearCurMapGo()
        end
        if self._storeCo ~= nil then
            cs_coroutine.stop(self._storeCo)
            self._storeCo = nil
        end
        --self._behaviourAction.UpdateAction = nil

        if not isNull(self._timeDown) then
            CDTimerModule.GetInstance():RemoveCD(self._timeDown)
            self._timeDown = nil
        end
        if self._co ~= nil then
            cs_coroutine.stop(self._co)
            self._co = nil
        end

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIActionCityStoreDialog
